const REQUIRED_FIELDS = ['request_id', 'user_id', 'recommended_group', 'change_type', 'justification'];
const VALID_CHANGE_TYPES = ['assign', 'revoke'];
const body = $input.item.json.body || {};
const missing = REQUIRED_FIELDS.filter(f => !body[f]);
if (missing.length > 0) {
  throw new Error('Missing required fields: ' + missing.join(', '));
}
if (!VALID_CHANGE_TYPES.includes(body.change_type)) {
  throw new Error('Invalid change_type. Must be assign or revoke.');
}
return $input.item;

