parameters.jsCode:
const assignments = $('Fetch All Permission Assignments').item.json.result?.structuredContent || [];
const auditLog = $('Fetch Audit Log History').item.json.result?.structuredContent || [];

const SOD_CONFLICT_PAIRS = [
  ['Compensation Planner', 'Compensation Approver'],
  ['Payroll Input', 'Payroll Approver'],
  ['PO Creator', 'PO Approver'],
  ['Recruiting Recruiter', 'Recruiting Admin']
];

const sodConflicts = [];
const bestPracticeDeviations = [];

for (const user of assignments) {
  const groups = user.permissionGroups || [];
  for (const [g1, g2] of SOD_CONFLICT_PAIRS) {
    if (groups.includes(g1) && groups.includes(g2)) {
      sodConflicts.push({ userId: user.userId, conflictingGroups: [g1, g2], riskLevel: 'High' });
    }
  }
  if (groups.some(g => g.toLowerCase().includes('admin') || g.toLowerCase().includes('super'))) {
    if (!['HR Admin', 'HR General', 'System Admin'].some(allowed => groups.includes(allowed))) {
      bestPracticeDeviations.push({ userId: user.userId, deviation: 'End user has broad admin permission group', fix: 'Review and revoke admin group' });
    }
  }
  if (!groups.includes('Employee Self-Service')) {
    bestPracticeDeviations.push({ userId: user.userId, deviation: 'Missing Employee Self-Service (ESS) group', fix: 'Assign ESS group' });
  }
}

const report = {
  period: `Q${Math.ceil((new Date().getMonth() + 1) / 3)} ${new Date().getFullYear()}`,
  generatedAt: new Date().toISOString(),
  totalUsersReviewed: assignments.length,
  sodConflictsDetected: sodConflicts.length,
  permissionChangesInPeriod: auditLog.length,
  bestPracticeDeviations: bestPracticeDeviations.length,
  sodConflicts,
  changeHistory: auditLog,
  deviations: bestPracticeDeviations
};

return [{ json: report }];

